/* JsonPathForge 纯函数内核：JSONPath tokenize / parse / exec（Goessner 语义） */
var JP = (function(){
  'use strict';
  var MISS = {miss:true};

  /* ---------- 词法：路径字符串 → token 数组 ---------- */
  function readName(s, i){
    var m = s.slice(i).match(/^[A-Za-z0-9_$\u00A0-\uFFFF-]+/);
    if(!m) return null;
    return { name: m[0], next: i + m[0].length };
  }
  /* 找到与 s[i]='[' 匹配的 ']'（跳过引号内与嵌套括号） */
  function matchBracket(s, i){
    var depth = 0, q = null;
    for(var j=i; j<s.length; j++){
      var c = s[j];
      if(q){ if(c === q && s[j-1] !== '\\') q = null; continue; }
      if(c === "'" || c === '"'){ q = c; continue; }
      if(c === '[' || c === '(') depth++;
      else if(c === ')') depth--;
      else if(c === ']'){ depth--; if(depth === 0) return j; }
    }
    throw new Error('未闭合的 [');
  }
  /* 顶层分割（跳过引号与括号） */
  function splitTop(s, sep){
    var parts = [], depth = 0, q = null, cur = '', i = 0;
    while(i < s.length){
      var c = s[i];
      if(q){ cur += c; if(c === q && s[i-1] !== '\\') q = null; i++; continue; }
      if(c === "'" || c === '"'){ q = c; cur += c; i++; continue; }
      if(c === '(' || c === '[') depth++;
      if(c === ')' || c === ']') depth--;
      if(depth === 0 && s.slice(i, i+sep.length) === sep){ parts.push(cur); cur = ''; i += sep.length; continue; }
      cur += c; i++;
    }
    parts.push(cur);
    return parts;
  }
  function parseLiteral(s){
    s = s.trim();
    var m;
    if((m = s.match(/^'((?:[^'\\]|\\.)*)'$/)) || (m = s.match(/^"((?:[^"\\]|\\.)*)"$/)))
      return { lit: m[1].replace(/\\(.)/g, '$1') };
    if(/^-?\d+(\.\d+)?([eE][+-]?\d+)?$/.test(s)) return { lit: parseFloat(s) };
    if(s === 'true') return { lit: true };
    if(s === 'false') return { lit: false };
    if(s === 'null') return { lit: null };
    if((m = s.match(/^\/(.+)\/([a-z]*)$/))) return { re: new RegExp(m[1], m[2]) };
    throw new Error('无法解析字面量: ' + s);
  }
  /* @ 访问器 → keys 数组 */
  function parseAt(s){
    s = s.trim();
    if(s[0] !== '@') throw new Error('过滤器左侧须以 @ 开头');
    var keys = [], i = 1;
    while(i < s.length){
      if(s[i] === '.'){
        var m = readName(s, i+1);
        if(!m) throw new Error('@ 后缺少属性名');
        keys.push(m.name); i = m.next;
      } else if(s[i] === '['){
        var e = matchBracket(s, i);
        var inner = s.slice(i+1, e).trim();
        var qm = inner.match(/^'((?:[^'\\]|\\.)*)'$/) || inner.match(/^"((?:[^"\\]|\\.)*)"$/);
        if(qm) keys.push(qm[1].replace(/\\(.)/g, '$1'));
        else if(/^-?\d+$/.test(inner)) keys.push(parseInt(inner, 10));
        else throw new Error('@[..] 仅支持字符串/整数下标');
        i = e + 1;
      } else throw new Error('@ 访问器语法错误: ' + s);
    }
    return keys;
  }
  var OPS = ['==','!=','<=','>=','=~','<','>'];
  function parseCond(s){
    s = s.trim();
    while(s[0] === '(' && s[s.length-1] === ')'){
      /* 仅当括号确实整体配对时剥离 */
      var d = 0, whole = true;
      for(var i=0;i<s.length;i++){
        if(s[i]==='(') d++; else if(s[i]===')'){ d--; if(d===0 && i < s.length-1){ whole=false; break; } }
      }
      if(!whole) break;
      s = s.slice(1, -1).trim();
    }
    /* 找顶层比较运算符 */
    var depth = 0, q = null;
    for(var j=0;j<s.length;j++){
      var c = s[j];
      if(q){ if(c===q && s[j-1] !== '\\') q = null; continue; }
      if(c === "'" || c === '"'){ q = c; continue; }
      if(c === '(' || c === '[') depth++;
      if(c === ')' || c === ']') depth--;
      if(depth === 0){
        for(var k=0;k<OPS.length;k++){
          if(s.slice(j, j+OPS[k].length) === OPS[k]){
            var lhs = s.slice(0, j).trim(), rhs = s.slice(j+OPS[k].length).trim();
            return { keys: parseAt(lhs), op: OPS[k], rhs: parseLiteral(rhs) };
          }
        }
      }
    }
    return { keys: parseAt(s), op: null, rhs: null }; /* 存在性判断 */
  }
  function parseFilter(expr){
    /* expr = ?(...) 的内部（已剥 ? 与外括号）；支持 && || */
    var ors = splitTop(expr, '||').map(function(part){
      return splitTop(part, '&&').map(parseCond);
    });
    return { ors: ors };
  }
  function parseBracket(inner){
    if(inner === '*') return { t: 'wild' };
    if(inner[0] === '?'){
      var body = inner.slice(1).trim();
      if(body[0] === '(' && body[body.length-1] === ')') body = body.slice(1, -1);
      return { t: 'filter', f: parseFilter(body), src: inner };
    }
    var parts = splitTop(inner, ',').map(function(p){ return p.trim(); });
    /* 引号名（可联合） */
    if(/^['"]/.test(parts[0])){
      var names = parts.map(function(p){
        var m = p.match(/^'((?:[^'\\]|\\.)*)'$/) || p.match(/^"((?:[^"\\]|\\.)*)"$/);
        if(!m) throw new Error('无效的引号名: ' + p);
        return m[1].replace(/\\(.)/g, '$1');
      });
      return { t: 'names', names: names };
    }
    /* 切片（顶层含 : 且非引号） */
    if(parts.length === 1 && inner.indexOf(':') >= 0){
      var seg = inner.split(':');
      if(seg.length > 3) throw new Error('切片最多 start:end:step 三段');
      function num(x, dflt){ x = x.trim(); return x === '' ? dflt : parseInt(x, 10); }
      var stp = num(seg[2] === undefined ? '' : seg[2], 1);
      if(stp === 0) throw new Error('切片 step 不能为 0');
      return { t: 'slice', start: num(seg[0], null), end: num(seg[1], null), step: stp };
    }
    /* 数字下标（可联合，支持负数） */
    var idxs = parts.map(function(p){
      if(!/^-?\d+$/.test(p)) throw new Error('无效下标: ' + p);
      return parseInt(p, 10);
    });
    return { t: 'idx', idxs: idxs };
  }
  function tokenize(path){
    if(typeof path !== 'string') throw new Error('path 必须是字符串');
    path = path.trim();
    if(!path) throw new Error('空路径');
    if(path[0] !== '$') throw new Error('路径必须以 $ 开头');
    var toks = [{ t: 'root' }], i = 1, n = path.length;
    while(i < n){
      var ch = path[i];
      if(ch === '.'){
        if(path[i+1] === '.'){
          i += 2;
          if(path[i] === '['){ toks.push({ t: 'descAny' }); continue; }
          if(path[i] === '*'){ toks.push({ t: 'desc', name: '*' }); i++; continue; }
          var m = readName(path, i);
          if(!m) throw new Error('.. 后缺少名称');
          toks.push({ t: 'desc', name: m.name }); i = m.next;
        } else {
          i += 1;
          if(path[i] === '*'){ toks.push({ t: 'wild' }); i++; continue; }
          var m2 = readName(path, i);
          if(!m2) throw new Error('. 后缺少名称');
          toks.push({ t: 'child', name: m2.name }); i = m2.next;
        }
      } else if(ch === '['){
        var e = matchBracket(path, i);
        toks.push(parseBracket(path.slice(i+1, e).trim()));
        i = e + 1;
      } else if(ch === ' '){ i++; }
      else throw new Error('位置 ' + i + ' 处意外字符 "' + ch + '"');
    }
    return toks;
  }

  /* ---------- 求值 ---------- */
  function isContainer(v){ return v !== null && typeof v === 'object'; }
  function getAt(node, keys){
    var cur = node;
    for(var i=0;i<keys.length;i++){
      if(!isContainer(cur)) return MISS;
      var k = keys[i];
      if(Array.isArray(cur)){
        if(typeof k !== 'number'){ return MISS; }
        var ix = k < 0 ? cur.length + k : k;
        if(ix < 0 || ix >= cur.length) return MISS;
        cur = cur[ix];
      } else {
        if(!Object.prototype.hasOwnProperty.call(cur, k)) return MISS;
        cur = cur[k];
      }
    }
    return cur;
  }
  function deepEq(a, b){
    if(a === b) return true;
    if(typeof a !== typeof b) return false;
    if(!isContainer(a) || !isContainer(b)) return false;
    return JSON.stringify(a) === JSON.stringify(b);
  }
  function evalCond(cond, item){
    var v = getAt(item, cond.keys);
    if(cond.op === null) return v !== MISS;
    if(v === MISS) return false;
    var r = cond.rhs;
    switch(cond.op){
      case '==': return r.re ? false : deepEq(v, r.lit);
      case '!=': return r.re ? true : !deepEq(v, r.lit);
      case '=~': return !!r.re && typeof v === 'string' && r.re.test(v);
      case '<':  return sameScalar(v, r.lit) && v <  r.lit;
      case '<=': return sameScalar(v, r.lit) && v <= r.lit;
      case '>':  return sameScalar(v, r.lit) && v >  r.lit;
      case '>=': return sameScalar(v, r.lit) && v >= r.lit;
    }
    return false;
  }
  function sameScalar(a, b){
    return (typeof a === 'number' && typeof b === 'number') || (typeof a === 'string' && typeof b === 'string');
  }
  function evalFilter(f, item){
    for(var i=0;i<f.ors.length;i++){
      var ands = f.ors[i], all = true;
      for(var j=0;j<ands.length;j++){ if(!evalCond(ands[j], item)){ all = false; break; } }
      if(all) return true;
    }
    return false;
  }
  function children(node){
    var out = [];
    if(Array.isArray(node.value)){
      for(var i=0;i<node.value.length;i++) out.push({ path: node.path.concat(i), value: node.value[i] });
    } else if(isContainer(node.value)){
      for(var k in node.value){
        if(Object.prototype.hasOwnProperty.call(node.value, k)) out.push({ path: node.path.concat(k), value: node.value[k] });
      }
    }
    return out;
  }
  /* 前序收集：node 自身 + 全部后代（值节点） */
  function descendantsAndSelf(node, out){
    out.push(node);
    var kids = children(node);
    for(var i=0;i<kids.length;i++) descendantsAndSelf(kids[i], out);
    return out;
  }
  function applyTok(tok, nodes){
    var out = [], i, j, n, kids;
    switch(tok.t){
      case 'root': return nodes;
      case 'child':
        for(i=0;i<nodes.length;i++){
          n = nodes[i];
          if(Array.isArray(n.value)){
            if(/^-?\d+$/.test(tok.name)){
              var ix = parseInt(tok.name, 10); if(ix < 0) ix += n.value.length;
              if(ix >= 0 && ix < n.value.length) out.push({ path: n.path.concat(ix), value: n.value[ix] });
            }
          } else if(isContainer(n.value) && Object.prototype.hasOwnProperty.call(n.value, tok.name)){
            out.push({ path: n.path.concat(tok.name), value: n.value[tok.name] });
          }
        }
        return out;
      case 'names':
        for(i=0;i<nodes.length;i++){
          n = nodes[i];
          for(j=0;j<tok.names.length;j++){
            var nm = tok.names[j];
            if(isContainer(n.value) && !Array.isArray(n.value) && Object.prototype.hasOwnProperty.call(n.value, nm))
              out.push({ path: n.path.concat(nm), value: n.value[nm] });
          }
        }
        return out;
      case 'wild':
        for(i=0;i<nodes.length;i++) out = out.concat(children(nodes[i]));
        return out;
      case 'desc':
        for(i=0;i<nodes.length;i++){
          var all = descendantsAndSelf(nodes[i], []);
          for(j=0;j<all.length;j++){
            if(tok.name === '*'){
              if(all[j] !== nodes[i]) out.push(all[j]); /* $..* = 除自身外的全部成员 */
            } else if(isContainer(all[j].value) && !Array.isArray(all[j].value) && Object.prototype.hasOwnProperty.call(all[j].value, tok.name)){
              out.push({ path: all[j].path.concat(tok.name), value: all[j].value[tok.name] });
            }
          }
        }
        return out;
      case 'descAny':
        for(i=0;i<nodes.length;i++) out = out.concat(descendantsAndSelf(nodes[i], []));
        return out;
      case 'idx':
        for(i=0;i<nodes.length;i++){
          n = nodes[i];
          if(!Array.isArray(n.value)) continue;
          for(j=0;j<tok.idxs.length;j++){
            var x = tok.idxs[j]; if(x < 0) x += n.value.length;
            if(x >= 0 && x < n.value.length) out.push({ path: n.path.concat(x), value: n.value[x] });
          }
        }
        return out;
      case 'slice':
        for(i=0;i<nodes.length;i++){
          n = nodes[i];
          if(!Array.isArray(n.value)) continue;
          var len = n.value.length, st = tok.step;
          if(!st) throw new Error('切片 step 不能为 0');
          var s0, e0;
          if(st > 0){
            s0 = tok.start === null ? 0 : (tok.start < 0 ? Math.max(0, len + tok.start) : Math.min(tok.start, len));
            e0 = tok.end === null ? len : (tok.end < 0 ? Math.max(0, len + tok.end) : Math.min(tok.end, len));
            for(j=s0;j<e0;j+=st) out.push({ path: n.path.concat(j), value: n.value[j] });
          } else {
            s0 = tok.start === null ? len - 1 : (tok.start < 0 ? len + tok.start : Math.min(tok.start, len - 1));
            e0 = tok.end === null ? -1 : (tok.end < 0 ? len + tok.end : tok.end);
            for(j=s0;j>e0;j+=st) if(j >= 0 && j < len) out.push({ path: n.path.concat(j), value: n.value[j] });
          }
        }
        return out;
      case 'filter':
        for(i=0;i<nodes.length;i++){
          kids = children(nodes[i]);
          for(j=0;j<kids.length;j++) if(evalFilter(tok.f, kids[j].value)) out.push(kids[j]);
        }
        return out;
    }
    throw new Error('未知 token: ' + tok.t);
  }
  function normalize(pathArr){
    var s = '$';
    for(var i=1;i<pathArr.length;i++){
      var k = pathArr[i];
      s += typeof k === 'number' ? '[' + k + ']' : "['" + String(k).replace(/'/g, "\\'") + "']";
    }
    return s;
  }
  /* run → [{path:'$[..]', value}]；query → 仅值数组 */
  function run(obj, path){
    var toks = typeof path === 'string' ? tokenize(path) : path;
    var nodes = [{ path: ['$'], value: obj }];
    for(var i=1;i<toks.length;i++){
      nodes = applyTok(toks[i], nodes);
      if(!nodes.length) return [];
    }
    return nodes.map(function(n){ return { path: normalize(n.path), value: n.value }; });
  }
  function query(obj, path){
    return run(obj, path).map(function(r){ return r.value; });
  }
  var SAMPLE = {
    store: {
      book: [
        { category: 'reference', author: 'Nigel Rees', title: 'Sayings of the Century', price: 8.95 },
        { category: 'fiction', author: 'Evelyn Waugh', title: 'Sword of Honour', price: 12.99 },
        { category: 'fiction', author: 'Herman Melville', title: 'Moby Dick', isbn: '0-553-21311-3', price: 8.99 },
        { category: 'fiction', author: 'J. R. R. Tolkien', title: 'The Lord of the Rings', isbn: '0-395-19395-8', price: 22.99 }
      ],
      bicycle: { color: 'red', price: 19.95 }
    },
    expensive: 10
  };
  return { tokenize: tokenize, run: run, query: query, normalize: normalize, sample: SAMPLE };
})();
if(typeof module!=='undefined' && module.exports){ module.exports = JP; }
if(typeof window!=='undefined'){ window.__JSONPATHFORGE__ = JP; }
